import{_ as i,C as r,o as l,c as h,j as d,a as e,E as o,a5 as c}from"./chunks/framework.CyyS6Zdm.js";const w=JSON.parse('{"title":"倒计时","description":"","frontmatter":{},"headers":[],"relativePath":"components/countdown.md","filePath":"components/countdown.md","lastUpdated":1787173379000}'),s={name:"components/countdown.md"},u={id:"倒计时",tabindex:"-1"};function b(p,t,m,f,x,q){const n=r("Badge"),a=r("XhDemo");return l(),h("div",null,[d("h1",u,[t[0]||(t[0]=e("倒计时 ",-1)),o(n,{type:"info",text:"countdown"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#倒计时","aria-label":'Permalink to "倒计时 <Badge type="info" text="countdown" />"'},"​",-1))]),t[3]||(t[3]=c('<p>从一个时长倒数到零，到点回调。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>验证码重发倒计时、限时活动、会话即将过期提醒。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>展示的是一个时刻而不是剩余时长：用<a href="./time">时间</a>。</li><li>表达任务进度：用<a href="./progress">进度条</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>format</code> 决定显示的模板，<code>precision</code> 决定精确到哪一位。</li><li><code>active</code> 可暂停继续。</li><li><code>live</code> 决定读屏播报的方式；每一段也可以由作者自己排版。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>给一个剩余毫秒就开始往下走，缺省模板是 HH:mm:ss；走到 0 就停住不再往下</p>',10)),o(a,{src:"countdown/01-basic"}),t[4]||(t[4]=d("h3",{id:"模板与精度",tabindex:"-1"},[e("模板与精度 "),d("a",{class:"header-anchor",href:"#模板与精度","aria-label":'Permalink to "模板与精度"'},"​")],-1)),t[5]||(t[5]=d("p",null,"format 里 H 时 m 分 s 秒 S 毫秒，重复字母的个数即最少位数；precision 决定读到的数有多细",-1)),o(a,{src:"countdown/02-format"}),t[6]||(t[6]=d("h3",{id:"自己排版每一段",tabindex:"-1"},[e("自己排版每一段 "),d("a",{class:"header-anchor",href:"#自己排版每一段","aria-label":'Permalink to "自己排版每一段"'},"​")],-1)),t[7]||(t[7]=d("p",null,"默认插槽给出拆好的时、分、秒、毫秒，想把每段装进独立的格子就自己写",-1)),o(a,{src:"countdown/03-slot"}),t[8]||(t[8]=d("h3",{id:"暂停、继续与到点",tabindex:"-1"},[e("暂停、继续与到点 "),d("a",{class:"header-anchor",href:"#暂停、继续与到点","aria-label":'Permalink to "暂停、继续与到点"'},"​")],-1)),t[9]||(t[9]=d("p",null,"active 翻假即停在当前剩余量，翻真从那里接着走；改 value 就是重新计时，到点派一次 finish",-1)),o(a,{src:"countdown/04-control"}),t[10]||(t[10]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-countdown&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhCountdown</code></td></tr><tr><td>状态机</td><td><code>countdownMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/countdown.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;countdown&quot;</code>：<strong><code>root</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>number</code></td><td></td><td>剩余毫秒，缺省 0。改写它即把剩余量落到新值并从那里重新计时。</td></tr><tr><td><code>format</code></td><td><code>string</code></td><td></td><td>模板，缺省 <code>HH:mm:ss</code>。H 时、m 分、s 秒、S 毫秒，重复字母的个数即最少位数。</td></tr><tr><td><code>active</code></td><td><code>boolean</code></td><td></td><td>是否在走，缺省 true。翻假即停在当前剩余量，翻真从那里接着走。</td></tr><tr><td><code>precision</code></td><td><code>number</code></td><td></td><td>取值粒度：0 到秒、1 到十分之一秒、2 到百分之一秒、3 到毫秒。缺省 0。</td></tr><tr><td><code>live</code></td><td><code>CountdownLive</code></td><td></td><td>读屏播报档位，缺省 off。</td></tr><tr><td><code>onFinish</code></td><td><code>(details: CountdownFinishDetails) =&gt; void</code></td><td></td><td>走到 0 时通知一次。中途被停掉不通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>finish</code></td><td><code>CountdownFinishDetails</code></td><td>走到 0；detail 为 <code>{ value: number }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhCountdown</code></td><td><code>default</code></td><td><code>CountdownSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;idle&#39; | &#39;running&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code> · <code>running</code></p><p><strong>事件</strong>：<code>RUN.START</code> · <code>RUN.STOP</code> · <code>RUN.SYNC</code> · <code>FRAME</code></p><p><strong>判据</strong>：<code>isSettled</code> · <code>isActive</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>phase</code></td><td><code>CountdownPhase</code></td><td></td></tr><tr><td><code>value</code></td><td><code>number</code></td><td>按精度量化后的剩余毫秒，也是拆分与铺字的输入。</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>按模板铺好的文本，也就是根里该显示的字。</td></tr><tr><td><code>parts</code></td><td><code>CountdownParts</code></td><td>拆开的时、分、秒、毫秒，给要自己排版每一段的作者用。</td></tr><tr><td><code>running</code></td><td><code>boolean</code></td><td>是否还在走。</td></tr><tr><td><code>finished</code></td><td><code>boolean</code></td><td>剩余量是否已经归零。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/TR/wai-aria-1.2/#status" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-live</code></td><td>props.live</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;status&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/countdown.css</code> 按部件选择：<code>[data-scope=&quot;countdown&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-finished</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;running&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-countdown-fg</code> · <code>--xh-countdown-finished-fg</code></p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./button">按钮</a>配合做重发倒计时；与<a href="./alert">警告提示</a>配合做过期提醒。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>精确到秒的倒计时不要开成高频播报，读屏用户会被打断得没法做事。</li><li>到点后要有明确的结束态，别停在 00:00 就不动了。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>倒计时结束不触发任何事，用户白等一场。</li><li>页面切到后台后计时漂移却不校正。</li></ul>',43))])}const g=i(s,[["render",b]]);export{w as __pageData,g as default};
